
/**
 * WheatGuard AI – A4 Diagnostic PDF Generator
 *
 * Recreates the single-page diagnostic report generated by
 * the backend reports.py using jsPDF.
 *
 * No html2canvas is used.
 * Everything is drawn programmatically for crisp PDF output.
 *
 * Usage:
 *   import { generatePredictionPdf } from "@/lib/generatePdf";
 *   await generatePredictionPdf(result);
 */

import type { PredictionResponse } from "@/types";

/* -------------------------------------------------------------------------- */
/* Colour palette                                                             */
/* -------------------------------------------------------------------------- */

type RGB = [number, number, number];

const C = {
  greenDark: [0, 54, 42] as RGB,
  greenMid: [0, 108, 73] as RGB,
  greenPale: [240, 253, 244] as RGB,

  white: [255, 255, 255] as RGB,

  redDark: [186, 26, 26] as RGB,
  redPale: [255, 245, 244] as RGB,

  orange: [234, 138, 0] as RGB,
  orangePale: [255, 248, 232] as RGB,

  yellow: [199, 128, 0] as RGB,

  grayText: [37, 42, 40] as RGB,
  grayMid: [102, 109, 105] as RGB,
  grayLight: [200, 204, 202] as RGB,
  grayPale: [247, 248, 247] as RGB,

  blue: [0, 91, 142] as RGB,

  gold: [199, 138, 8] as RGB,
} as const;

/* -------------------------------------------------------------------------- */
/* A4 layout                                                                  */
/* -------------------------------------------------------------------------- */

const A4_W = 210;
const A4_H = 297;

const ML = 5.1;
const MR = 5.1;

/* -------------------------------------------------------------------------- */
/* Disease helpers                                                            */
/* -------------------------------------------------------------------------- */

const SEVERITY_FROM_CLASS: Record<string, string> = {
  healthy: "none",

  "leaf rust": "high",
  leaf_rust: "high",

  "brown rust": "high",
  brown_rust: "high",

  "yellow rust": "high",
  yellow_rust: "high",

  "stem rust": "critical",
  stem_rust: "critical",

  "powdery mildew": "moderate",
  powdery_mildew: "moderate",

  "septoria leaf blotch": "high",
  septoria_leaf_blotch: "high",

  "fusarium head blight": "critical",
  fusarium_head_blight: "critical",

  "tan spot": "moderate",
  tan_spot: "moderate",
};

const DISEASE_ALIASES: Record<string, string> = {
  "stem rust": "Black Rust",
  stem_rust: "Black Rust",

  "leaf rust": "Brown Rust",
  leaf_rust: "Brown Rust",

  "yellow rust": "Yellow Rust",
  yellow_rust: "Yellow Rust",
};

/* -------------------------------------------------------------------------- */
/* Generic helpers                                                            */
/* -------------------------------------------------------------------------- */

function humaniseClass(raw: string | undefined | null): string {
  return String(raw ?? "Unknown disease")
    .replace(/_/g, " ")
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function deriveSeverity(disease: string): string {
  const key = disease.toLowerCase().trim();
  return SEVERITY_FROM_CLASS[key] ?? "unknown";
}

function severityColour(severity: string): RGB {
  switch (severity.toLowerCase()) {
    case "critical":
      return C.redDark;

    case "high":
      return C.orange;

    case "moderate":
      return C.yellow;

    case "none":
      return C.greenMid;

    default:
      return C.greenMid;
  }
}

function confidenceColour(confidence: number): RGB {
  if (confidence >= 80) return C.greenMid;
  if (confidence >= 60) return C.yellow;
  if (confidence >= 40) return C.orange;
  return C.redDark;
}

function confidenceValue(result: PredictionResponse): number {
  const raw = Number(result.confidence_percentage ?? 0);

  if (!Number.isFinite(raw)) return 0;

  if (raw >= 0 && raw <= 1) {
    return Math.max(0, Math.min(100, raw * 100));
  }

  return Math.max(0, Math.min(100, raw));
}

function fitText(value: unknown, maxChars: number): string {
  const text = String(value ?? "").trim();

  if (text.length <= maxChars) {
    return text;
  }

  return `${text.slice(0, maxChars - 1).trim()}…`;
}

function normaliseText(value: unknown): string {
  if (value == null) return "";

  if (Array.isArray(value)) {
    return value
      .filter((v) => String(v).trim())
      .map((v) => `• ${String(v).trim()}`)
      .join("\n");
  }

  if (typeof value === "object") {
    return Object.entries(value as Record<string, unknown>)
      .map(([key, val]) => `• ${key}: ${String(val)}`)
      .join("\n");
  }

  return String(value).trim();
}

/* -------------------------------------------------------------------------- */
/* PDF helpers                                                                */
/* -------------------------------------------------------------------------- */

function setFont(
  doc: any,
  size: number,
  style: "normal" | "bold" | "italic" = "normal",
  colour: RGB = C.grayText
) {
  doc.setFont("helvetica", style);
  doc.setFontSize(size);
  doc.setTextColor(...colour);
}

function fillRect(
  doc: any,
  x: number,
  y: number,
  w: number,
  h: number,
  colour: RGB
) {
  doc.setFillColor(...colour);
  doc.rect(x, y, w, h, "F");
}

function strokeRect(
  doc: any,
  x: number,
  y: number,
  w: number,
  h: number,
  colour: RGB = C.grayLight,
  lineWidth = 0.3
) {
  doc.setDrawColor(...colour);
  doc.setLineWidth(lineWidth);
  doc.rect(x, y, w, h, "S");
}

function roundedRect(
  doc: any,
  x: number,
  y: number,
  w: number,
  h: number,
  fill: RGB | null,
  line: RGB | null = null,
  lineWidth = 0.3,
  radius = 2
) {
  if (fill) {
    doc.setFillColor(...fill);
  }

  if (line) {
    doc.setDrawColor(...line);
    doc.setLineWidth(lineWidth);
  }

  doc.roundedRect(
    x,
    y,
    w,
    h,
    radius,
    radius,
    fill && line ? "FD" : fill ? "F" : line ? "S" : undefined
  );
}

function line(
  doc: any,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  colour: RGB = C.grayLight,
  width = 0.3
) {
  doc.setDrawColor(...colour);
  doc.setLineWidth(width);
  doc.line(x1, y1, x2, y2);
}

function addText(
  doc: any,
  value: string,
  x: number,
  y: number,
  options?: {
    align?: "left" | "center" | "right";
    maxWidth?: number;
  }
) {
  doc.text(String(value ?? ""), x, y, {
    align: options?.align ?? "left",
    maxWidth: options?.maxWidth,
  });
}

function addWrappedText(
  doc: any,
  value: string,
  x: number,
  y: number,
  width: number,
  lineHeight: number
): number {
  const lines = doc.splitTextToSize(String(value ?? ""), width) as string[];

  lines.forEach((item, index) => {
    doc.text(item, x, y + index * lineHeight);
  });

  return y + lines.length * lineHeight;
}

/* -------------------------------------------------------------------------- */
/* Logo                                                                       */
/* -------------------------------------------------------------------------- */

function addLogo(doc: any, x: number, y: number, scale = 1) {
  const w = 11 * scale;
  const h = 13 * scale;

  /*
   * Outer shield / wheat emblem.
   *
   * jsPDF does not have PowerPoint's pentagon primitive,
   * so we approximate it with a polygon.
   */

  doc.setDrawColor(...C.greenDark);
  doc.setLineWidth(0.55);

  doc.lines(
    [
      [w * 0.5, 0],
      [w * 0.5, h * 0.75],
      [-w * 0.20, h * 0.25],
      [-w * 0.30, -h * 0.45],
      [0, -h * 0.55],
    ],
    x,
    y,
    [1, 1],
    "S",
    true
  );

  /* Central wheat stem */
  fillRect(
    doc,
    x + w * 0.47,
    y + h * 0.18,
    w * 0.06,
    h * 0.65,
    C.gold
  );

  /* Wheat grains */
  for (let i = 0; i < 5; i++) {
    const yy = y + h * 0.17 + i * h * 0.12;

    doc.setFillColor(...C.gold);

    doc.ellipse(
      x + w * 0.33,
      yy,
      w * 0.15,
      h * 0.055,
      "F"
    );

    doc.ellipse(
      x + w * 0.53,
      yy + h * 0.035,
      w * 0.15,
      h * 0.055,
      "F"
    );
  }
}

/* -------------------------------------------------------------------------- */
/* Leaf icon                                                                  */
/* -------------------------------------------------------------------------- */

function addLeafIcon(
  doc: any,
  x: number,
  y: number,
  size: number,
  colour: RGB
) {
  doc.setDrawColor(...colour);
  doc.setLineWidth(0.45);

  doc.ellipse(
    x + size * 0.20,
    y + size * 0.25,
    size * 0.40,
    size * 0.22,
    "S"
  );

  fillRect(
    doc,
    x + size * 0.49,
    y + size * 0.15,
    size * 0.035,
    size * 0.50,
    colour
  );
}

/* -------------------------------------------------------------------------- */
/* Alert icon                                                                 */
/* -------------------------------------------------------------------------- */

function addAlertIcon(
  doc: any,
  x: number,
  y: number,
  size: number,
  colour: RGB
) {
  doc.setFillColor(...colour);

  doc.triangle(
    x + size / 2,
    y,
    x + size,
    y + size,
    x,
    y + size,
    "F"
  );

  setFont(doc, size * 18, "bold", C.white);

  addText(
    doc,
    "!",
    x + size / 2,
    y + size * 0.73,
    { align: "center" }
  );
}

/* -------------------------------------------------------------------------- */
/* Stopwatch icon                                                             */
/* -------------------------------------------------------------------------- */

function addStopwatchIcon(
  doc: any,
  x: number,
  y: number,
  size: number
) {
  doc.setDrawColor(...C.greenDark);
  doc.setLineWidth(0.45);

  doc.circle(
    x + size * 0.45,
    y + size * 0.57,
    size * 0.38,
    "S"
  );

  fillRect(
    doc,
    x + size * 0.31,
    y,
    size * 0.25,
    size * 0.14,
    C.greenDark
  );

  fillRect(
    doc,
    x + size * 0.43,
    y + size * 0.48,
    size * 0.035,
    size * 0.22,
    C.greenDark
  );

  fillRect(
    doc,
    x + size * 0.43,
    y + size * 0.57,
    size * 0.20,
    size * 0.035,
    C.greenDark
  );
}

/* -------------------------------------------------------------------------- */
/* Gauge                                                                      */
/* -------------------------------------------------------------------------- */

function addGauge(
  doc: any,
  cx: number,
  cy: number,
  radius: number,
  percentage: number,
  colour: RGB
) {
  const pct = Math.max(0, Math.min(100, percentage));

  const start = Math.PI;
  const end = 0;

  const steps = 60;

  /*
   * Track
   */
  doc.setDrawColor(...C.grayLight);
  doc.setLineWidth(radius * 0.25);

  const trackPoints: [number, number][] = [];

  for (let i = 0; i <= steps; i++) {
    const angle = start + (end - start) * (i / steps);

    trackPoints.push([
      cx + radius * Math.cos(angle),
      cy + radius * Math.sin(angle),
    ]);
  }

  for (let i = 0; i < trackPoints.length - 1; i++) {
    line(
      doc,
      trackPoints[i][0],
      trackPoints[i][1],
      trackPoints[i + 1][0],
      trackPoints[i + 1][1],
      C.grayLight,
      radius * 0.25
    );
  }

  /*
   * Progress
   */
  const progressSteps = Math.max(
    1,
    Math.round(steps * (pct / 100))
  );

  for (let i = 0; i < progressSteps; i++) {
    const a1 =
      start +
      (end - start) *
        (i / steps);

    const a2 =
      start +
      (end - start) *
        ((i + 1) / steps);

    line(
      doc,
      cx + radius * Math.cos(a1),
      cy + radius * Math.sin(a1),
      cx + radius * Math.cos(a2),
      cy + radius * Math.sin(a2),
      colour,
      radius * 0.25
    );
  }
}

/* -------------------------------------------------------------------------- */
/* Decorative wheat                                                           */
/* -------------------------------------------------------------------------- */

function addWheatDecor(
  doc: any,
  x: number,
  y: number,
  size: number,
  colour: RGB
) {
  fillRect(
    doc,
    x + size * 0.47,
    y + size * 0.06,
    size * 0.03,
    size * 0.90,
    colour
  );

  for (let i = 0; i < 6; i++) {
    const yy = y + size * 0.06 + i * size * 0.13;

    doc.setFillColor(...colour);

    doc.ellipse(
      x + size * 0.24,
      yy,
      size * 0.13,
      size * 0.055,
      "F"
    );

    doc.ellipse(
      x + size * 0.56,
      yy + size * 0.05,
      size * 0.13,
      size * 0.055,
      "F"
    );
  }
}

/* -------------------------------------------------------------------------- */
/* Clipboard decoration                                                       */
/* -------------------------------------------------------------------------- */

function addClipboardDecor(
  doc: any,
  x: number,
  y: number,
  size: number,
  colour: RGB
) {
  roundedRect(
    doc,
    x,
    y + size * 0.08,
    size,
    size * 0.82,
    null,
    colour,
    0.7,
    2
  );

  roundedRect(
    doc,
    x + size * 0.30,
    y,
    size * 0.40,
    size * 0.16,
    colour,
    null,
    0,
    1
  );

  for (let i = 0; i < 3; i++) {
    fillRect(
      doc,
      x + size * 0.18,
      y + size * 0.32 + i * size * 0.22,
      size * 0.64,
      size * 0.07,
      colour
    );
  }
}

/* -------------------------------------------------------------------------- */
/* Shield decoration                                                          */
/* -------------------------------------------------------------------------- */

function addShieldDecor(
  doc: any,
  x: number,
  y: number,
  size: number,
  colour: RGB
) {
  doc.setDrawColor(...colour);
  doc.setLineWidth(0.7);

  const points = [
    [x + size * 0.39, y],
    [x + size * 0.78, y + size * 0.12],
    [x + size * 0.70, y + size * 0.70],
    [x + size * 0.39, y + size],
    [x + size * 0.08, y + size * 0.70],
    [x, y + size * 0.12],
  ];

  for (let i = 0; i < points.length; i++) {
    const p1 = points[i];
    const p2 = points[(i + 1) % points.length];

    line(
      doc,
      p1[0],
      p1[1],
      p2[0],
      p2[1],
      colour,
      0.7
    );
  }

  /*
   * Check mark
   */
  line(
    doc,
    x + size * 0.20,
    y + size * 0.48,
    x + size * 0.34,
    y + size * 0.63,
    colour,
    1
  );

  line(
    doc,
    x + size * 0.34,
    y + size * 0.63,
    x + size * 0.61,
    y + size * 0.32,
    colour,
    1
  );
}

/* -------------------------------------------------------------------------- */
/* Section card                                                               */
/* -------------------------------------------------------------------------- */

function addSectionCard(
  doc: any,
  y: number,
  height: number,
  title: string,
  body: string,
  accent: RGB,
  bg: RGB,
  icon: string,
  decoration: "wheat" | "clipboard" | "shield"
) {
  const x = 4.6;
  const w = A4_W - 9.2;

  roundedRect(
    doc,
    x,
    y,
    w,
    height,
    bg,
    accent,
    0.3,
    2.3
  );

  /*
   * Icon circle
   */
  doc.setFillColor(...accent);
  doc.circle(
    x + 8.5,
    y + 8.0,
    4.3,
    "F"
  );

  setFont(doc, 12, "bold", C.white);

  addText(
    doc,
    icon,
    x + 8.5,
    y + 10,
    { align: "center" }
  );

  /*
   * Title
   */
  setFont(doc, 12, "bold", accent);

  addText(
    doc,
    title.toUpperCase(),
    x + 15,
    y + 8.5
  );

  /*
   * Decoration
   */
  const decorSize = Math.min(height - 8, 22);

  const decorX = x + w - decorSize - 7;
  const decorY = y + (height - decorSize) / 2;

  if (decoration === "wheat") {
    addWheatDecor(
      doc,
      decorX,
      decorY,
      decorSize,
      accent
    );
  }

  if (decoration === "clipboard") {
    addClipboardDecor(
      doc,
      decorX,
      decorY,
      decorSize,
      accent
    );
  }

  if (decoration === "shield") {
    addShieldDecor(
      doc,
      decorX,
      decorY,
      decorSize,
      accent
    );
  }

  /*
   * Body
   */
  setFont(doc, 9.2, "normal", C.grayText);

  const bodyWidth =
    w -
    15 -
    decorSize -
    9;

  addWrappedText(
    doc,
    fitText(body, 340),
    x + 15,
    y + 15,
    bodyWidth,
    4.1
  );
}

/* -------------------------------------------------------------------------- */
/* Image loading                                                              */
/* -------------------------------------------------------------------------- */

async function loadImageAsDataUrl(
  source: unknown
): Promise<string | null> {
  if (!source) return null;

  const value = String(source).trim();

  if (!value) return null;

  if (
    value.startsWith("data:image/")
  ) {
    return value;
  }

  try {
    /*
     * URL image
     */
    if (
      value.startsWith("http://") ||
      value.startsWith("https://")
    ) {
      const response = await fetch(value);

      if (!response.ok) {
        throw new Error(
          `Image request failed: ${response.status}`
        );
      }

      const blob = await response.blob();

      return await blobToDataUrl(blob);
    }

    return value;
  } catch (error) {
    console.warn(
      "WheatGuard PDF image could not be loaded:",
      error
    );

    return null;
  }
}

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = () => {
      resolve(String(reader.result));
    };

    reader.onerror = reject;

    reader.readAsDataURL(blob);
  });
}

/* -------------------------------------------------------------------------- */
/* Image card                                                                 */
/* -------------------------------------------------------------------------- */

async function addImageCard(
  doc: any,
  x: number,
  y: number,
  w: number,
  h: number,
  imageSource: unknown,
  filename: string
) {
  roundedRect(
    doc,
    x,
    y,
    w,
    h,
    C.white,
    C.grayLight,
    0.3,
    2
  );

  /*
   * Green title bar
   */
  fillRect(
    doc,
    x,
    y,
    w,
    11.7,
    C.greenDark
  );

  addLeafIcon(
    doc,
    x + 4.5,
    y + 3.1,
    5,
    C.white
  );

  setFont(doc, 10.5, "bold", C.white);

  addText(
    doc,
    "WHEAT LEAF IMAGE",
    x + 12.5,
    y + 7.6
  );

  /*
   * Image area
   */
  const ix = x + 3.6;
  const iy = y + 15.2;
  const iw = w - 7.2;
  const ih = 53.9;

  const imageData = await loadImageAsDataUrl(
    imageSource
  );

  if (imageData) {
    try {
      doc.addImage(
        imageData,
        "JPEG",
        ix,
        iy,
        iw,
        ih,
        undefined,
        "FAST"
      );
    } catch {
      try {
        doc.addImage(
          imageData,
          "PNG",
          ix,
          iy,
          iw,
          ih,
          undefined,
          "FAST"
        );
      } catch {
        addImagePlaceholder(
          doc,
          ix,
          iy,
          iw,
          ih
        );
      }
    }
  } else {
    addImagePlaceholder(
      doc,
      ix,
      iy,
      iw,
      ih
    );
  }

  /*
   * Record indicator
   */
  doc.setFillColor(...C.greenMid);

  doc.circle(
    x + 13,
    y + 73.2,
    3.5,
    "F"
  );

  setFont(doc, 8.5, "bold", C.white);

  addText(
    doc,
    "▧",
    x + 13,
    y + 75,
    { align: "center" }
  );

  setFont(doc, 8.5, "bold", C.grayText);

  addText(
    doc,
    "Record 1/1",
    x + 21,
    y + 75
  );

  setFont(doc, 7.2, "normal", C.grayMid);

  addText(
    doc,
    fitText(filename, 48),
    x + w / 2,
    y + 82,
    { align: "center", maxWidth: w - 8 }
  );
}

function addImagePlaceholder(
  doc: any,
  x: number,
  y: number,
  w: number,
  h: number
) {
  roundedRect(
    doc,
    x,
    y,
    w,
    h,
    [233, 242, 232],
    C.grayLight,
    0.3,
    2
  );

  addLeafIcon(
    doc,
    x + w * 0.42,
    y + 20,
    13,
    C.greenMid
  );

  setFont(doc, 13, "bold", C.greenDark);

  addText(
    doc,
    "WHEAT LEAF IMAGE",
    x + w / 2,
    y + 39,
    { align: "center" }
  );

  setFont(doc, 8, "normal", C.grayMid);

  addText(
    doc,
    "Image unavailable",
    x + w / 2,
    y + 46,
    { align: "center" }
  );
}

/* -------------------------------------------------------------------------- */
/* Main generator                                                             */
/* -------------------------------------------------------------------------- */

export async function generatePredictionPdf(
  result: PredictionResponse
): Promise<void> {
  const { jsPDF } = await import("jspdf");

  const doc = new jsPDF({
    orientation: "portrait",
    unit: "mm",
    format: "a4",
    compress: true,
  });

  const disease = humaniseClass(
    result.prediction
  );

  const severity =
    String(
      result.severity ||
        deriveSeverity(disease)
    ).toLowerCase();

  const confidence =
    confidenceValue(result);

  const sevColour =
    severityColour(severity);

  const confColour =
    confidenceColour(confidence);

  const modelVersion =
    String(
      result.model_version ?? "—"
    );

  const inferenceText =
    result.inference_time_ms != null
      ? `${Number(result.inference_time_ms).toFixed(0)} ms`
      : "—";

  const filename =
    String(
      (result as any).filename ??
        "—"
    );

  const alias =
    (result as any).disease_info
      ?.disease_alias ??
    DISEASE_ALIASES[
      disease.toLowerCase()
    ] ??
    "";

  const diseaseInfo =
    (result as any).disease_info;

  const problem =
    normaliseText(
      (result as any).problem ??
        diseaseInfo?.description
    ) ||
    `The wheat leaf image indicates signs associated with ${disease}. Review the affected plant area carefully and confirm the condition in the field.`;

  const recommendation =
    normaliseText(
      result.recommendation ??
        (result as any).recommendation
    ) ||
    (
      confidence < 40
        ? "⚠ Low confidence prediction. Please upload a clearer wheat-leaf image.\nContact a qualified agronomist if symptoms persist or spread."
        : "Inspect nearby plants for similar symptoms and follow your local wheat disease-management guidance."
    );

  const solution =
    normaliseText(
      (result as any).solution ??
        diseaseInfo?.management
    ) ||
    "Use an appropriate, locally approved management treatment when the disease is confirmed. Follow label instructions and agronomic advice.";

  /*
   * =========================================================================
   * HEADER
   * =========================================================================
   */

  addLogo(
    doc,
    7.6,
    5.8,
    1
  );

  setFont(
    doc,
    25,
    "bold",
    C.greenDark
  );

  addText(
    doc,
    "WheatGuard AI",
    23.4,
    12.7
  );

  setFont(
    doc,
    10.5,
    "normal",
    C.grayText
  );

  addText(
    doc,
    "Precision Wheat Disease Prediction System",
    23.8,
    18.5
  );

  setFont(
    doc,
    13.5,
    "bold",
    C.greenDark
  );

  addText(
    doc,
    "FIELD DIAGNOSTIC REPORT",
    200,
    12.8,
    { align: "right" }
  );

  /*
   * Header green line
   */
  fillRect(
    doc,
    5,
    25.5,
    200,
    0.9,
    C.greenMid
  );

  doc.setFillColor(...C.greenMid);

  doc.circle(
    203,
    25.95,
    1.4,
    "F"
  );

  /*
   * =========================================================================
   * MAIN CARDS
   * =========================================================================
   */

  const leftX = 5;
  const leftW = 88.4;

  const rightX = 98;
  const rightW = 107;

  const cardY = 31.8;
  const cardH = 95.5;

  await addImageCard(
    doc,
    leftX,
    cardY,
    leftW,
    cardH,
    (result as any).image_url ??
      (result as any).image_path ??
      (result as any).file_path ??
      (result as any).image,
    filename
  );

  /*
   * Disease card
   */
  roundedRect(
    doc,
    rightX,
    cardY,
    rightW,
    cardH,
    C.white,
    C.grayLight,
    0.35,
    2
  );

  addAlertIcon(
    doc,
    rightX + 14,
    cardY + 5,
    7,
    C.redDark
  );

  setFont(
    doc,
    12,
    "bold",
    C.redDark
  );

  addText(
    doc,
    "DISEASE DETECTED",
    rightX + 25,
    cardY + 12
  );

  setFont(
    doc,
    27,
    "bold",
    sevColour
  );

  addText(
    doc,
    fitText(disease, 22),
    rightX + rightW / 2,
    cardY + 29,
    {
      align: "center",
      maxWidth: rightW - 10,
    }
  );

  if (alias) {
    setFont(
      doc,
      15,
      "bold",
      C.grayText
    );

    addText(
      doc,
      `(${alias})`,
      rightX + rightW / 2,
      cardY + 39,
      {
        align: "center",
      }
    );
  }

  fillRect(
    doc,
    rightX + 4,
    cardY + 45,
    rightW - 8,
    0.45,
    C.redDark
  );

  /*
   * Three metrics
   */
  const colW = rightW / 3;

  const metricY =
    cardY + 51;

  /*
   * Confidence
   */
  setFont(
    doc,
    7.2,
    "bold",
    C.grayText
  );

  addText(
    doc,
    "AI CONFIDENCE",
    rightX + colW / 2,
    metricY,
    { align: "center" }
  );

  setFont(
    doc,
    17,
    "bold",
    confColour
  );

  addText(
    doc,
    `${confidence.toFixed(0)}%`,
    rightX + colW / 2,
    metricY + 8,
    { align: "center" }
  );

  addGauge(
    doc,
    rightX + colW / 2,
    metricY + 24,
    10,
    confidence,
    confColour
  );

  /*
   * Severity
   */
  setFont(
    doc,
    7.2,
    "bold",
    C.grayText
  );

  addText(
    doc,
    "SEVERITY",
    rightX + colW * 1.5,
    metricY,
    { align: "center" }
  );

  setFont(
    doc,
    15,
    "bold",
    sevColour
  );

  addText(
    doc,
    severity.charAt(0).toUpperCase() +
      severity.slice(1),
    rightX + colW * 1.5,
    metricY + 10,
    { align: "center" }
  );

  /*
   * Model
   */
  setFont(
    doc,
    7.2,
    "bold",
    C.grayText
  );

  addText(
    doc,
    "MODEL VERSION",
    rightX + colW * 2.5,
    metricY,
    { align: "center" }
  );

  setFont(
    doc,
    10.2,
    "bold",
    C.greenDark
  );

  addWrappedText(
    doc,
    modelVersion,
    rightX + colW * 2.5 - 15,
    metricY + 8,
    30,
    4
  );

  /*
   * Inference
   */
  addStopwatchIcon(
    doc,
    rightX + 43,
    cardY + 71.5,
    7
  );

  setFont(
    doc,
    9.5,
    "bold",
    C.grayText
  );

  addText(
    doc,
    `Inference: ${inferenceText}`,
    rightX + 52,
    cardY + 76
  );

  /*
   * Low confidence
   */
  if (
    Boolean(
      (result as any).low_confidence
    ) ||
    confidence < 40
  ) {
    roundedRect(
      doc,
      rightX + 4,
      cardY + 82.5,
      rightW - 8,
      11,
      C.orangePale,
      C.orange,
      0.3,
      2
    );

    addAlertIcon(
      doc,
      rightX + 35,
      cardY + 84.7,
      5,
      C.orange
    );

    setFont(
      doc,
      9.5,
      "bold",
      C.orange
    );

    addText(
      doc,
      "LOW CONFIDENCE",
      rightX + 45,
      cardY + 91.5
    );
  }

  /*
   * =========================================================================
   * INFORMATION CARDS
   * =========================================================================
   */

  addSectionCard(
    doc,
    135.6,
    33.5,
    "Problem",
    problem,
    C.redDark,
    C.redPale,
    "!",
    "wheat"
  );

  addSectionCard(
    doc,
    172.5,
    37,
    "Recommendation",
    recommendation,
    C.orange,
    C.orangePale,
    "!",
    "clipboard"
  );

  addSectionCard(
    doc,
    213.4,
    33,
    "Solution",
    solution,
    C.greenMid,
    C.greenPale,
    "✓",
    "shield"
  );

  /*
   * =========================================================================
   * KPI STRIP
   * =========================================================================
   */

  const stripY = 251.8;
  const stripH = 17.2;

  roundedRect(
    doc,
    4.6,
    stripY,
    200.8,
    stripH,
    C.white,
    C.grayLight,
    0.3,
    2
  );

  const cellW = 200.8 / 4;

  const metrics = [
    [
      "CONFIDENCE",
      `${confidence.toFixed(0)}%`,
      confColour,
    ],
    [
      "SEVERITY",
      severity.toUpperCase(),
      sevColour,
    ],
    [
      "INFERENCE",
      inferenceText,
      C.greenDark,
    ],
    [
      "STATUS",
      "AI PREDICTION",
      C.blue,
    ],
  ] as const;

  metrics.forEach(
    ([label, value, colour], index) => {
      const x =
        4.6 +
        index * cellW;

      if (index > 0) {
        fillRect(
          doc,
          x,
          stripY + 3,
          0.35,
          stripH - 6,
          C.grayLight
        );
      }

      setFont(
        doc,
        7.2,
        "bold",
        C.grayText
      );

      addText(
        doc,
        label,
        x + cellW / 2,
        stripY + 6.5,
        { align: "center" }
      );

      setFont(
        doc,
        value.length > 12 ? 8.5 : 12,
        "bold",
        colour
      );

      addText(
        doc,
        value,
        x + cellW / 2,
        stripY + 13.2,
        { align: "center" }
      );
    }
  );

  /*
   * =========================================================================
   * FOOTER
   * =========================================================================
   */

  setFont(
    doc,
    8.4,
    "bold",
    C.greenDark
  );

  addText(
    doc,
    `WheatGuard AI  ·  Field Diagnostic Report  ·  ${disease}`,
    A4_W / 2,
    276.5,
    {
      align: "center",
      maxWidth: 195,
    }
  );

  fillRect(
    doc,
    5,
    279.5,
    200,
    0.4,
    C.grayLight
  );

  addLogo(
    doc,
    13,
    283,
    0.72
  );

  setFont(
    doc,
    7.2,
    "normal",
    C.grayText
  );

  addText(
    doc,
    "AI predictions only. Always consult a qualified agricultural expert before applying treatments.",
    27,
    286.8,
    {
      maxWidth: 170,
    }
  );

  setFont(
    doc,
    6.8,
    "normal",
    C.grayMid
  );

  addText(
    doc,
    "WheatGuard AI — Precision Wheat Disease Prediction System",
    27,
    293.1,
    {
      maxWidth: 170,
    }
  );

  /*
   * Bottom green footer bar
   */
  fillRect(
    doc,
    4.6,
    295,
    200.8,
    2,
    C.greenDark
  );

  setFont(
    doc,
    6.8,
    "normal",
    C.white
  );

  addText(
    doc,
    "WheatGuard AI © 2026 — Precision Wheat Disease Prediction System",
    A4_W / 2,
    296.5,
    { align: "center" }
  );

  /*
   * =========================================================================
   * SAVE
   * =========================================================================
   */

  const dateStr =
    new Date()
      .toISOString()
      .slice(0, 10);

  const safeDisease =
    humaniseClass(disease)
      .replace(/[^a-zA-Z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "");

  doc.save(
    `WheatGuard_Report_${safeDisease}_${dateStr}.pdf`
  );
}
